#!/usr/bin/env node
// Generates the `ant apply` files (Markdown with YAML front matter, body = system prompt) and MODELS.md from the
// JSON source in docs/meta/agents-v3. One source, no hand sync. The lead's predefined_agents become relative
// file paths (`./nemo-po.md`), which `ant apply` resolves to agent IDs in dependency order (CLI ≥ 1.40.0).
// Usage: node scripts/agents/to-ant.mjs [dir]            write nemo-*.md + MODELS.md
//        node scripts/agents/to-ant.mjs --check [dir]    exit 1 when a generated file is stale (CI/PR proof)
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const args = process.argv.slice(2);
const check = args.includes("--check");
const here = path.dirname(fileURLToPath(import.meta.url));
const dir = path.resolve(
  args.find((a) => !a.startsWith("--")) ??
    path.join(here, "../../docs/meta/agents-v3"),
);

const files = fs
  .readdirSync(dir)
  .filter((f) => /^nemo-.*\.json$/.test(f))
  .sort();
const siblings = new Set(files.map((f) => f.replace(/\.json$/, "")));

function yamlScalar(v) {
  if (typeof v === "boolean" || typeof v === "number") return String(v);
  if (v === null) return "null";
  const s = String(v);
  // plain scalar only for safe identifiers/paths; everything else (digits, dots, trailing colon/dash, yes/no…) is quoted
  if (
    /^[A-Za-z_/][A-Za-z0-9_./-]*$/.test(s) &&
    !/[:-]$/.test(s) &&
    !/^(true|false|null|yes|no|on|off|y|n)$/i.test(s)
  )
    return s;
  return JSON.stringify(s);
}
function yaml(v, indent = 0) {
  const pad = " ".repeat(indent);
  if (Array.isArray(v)) {
    if (v.length === 0) return pad + "[]\n";
    return v
      .map((item) => {
        if (item !== null && typeof item === "object")
          return pad + "- " + yaml(item, indent + 2).trimStart();
        return pad + "- " + yamlScalar(item) + "\n";
      })
      .join("");
  }
  if (v !== null && typeof v === "object") {
    const ks = Object.keys(v);
    if (ks.length === 0) return pad + "{}\n";
    return ks
      .map((k) => {
        const val = v[k];
        if (val !== null && typeof val === "object") {
          if (Array.isArray(val) && val.length === 0)
            return `${pad}${yamlScalar(k)}: []\n`;
          if (!Array.isArray(val) && Object.keys(val).length === 0)
            return `${pad}${yamlScalar(k)}: {}\n`;
          return `${pad}${yamlScalar(k)}:\n${yaml(val, indent + 2)}`;
        }
        return `${pad}${yamlScalar(k)}: ${yamlScalar(val)}\n`;
      })
      .join("");
  }
  return pad + yamlScalar(v) + "\n";
}

function toAnt(a) {
  const fm = { name: a.name };
  if (a.description) fm.description = a.description;
  fm.model = a.model;
  if (a.tools) fm.tools = a.tools;
  if (a.mcp_servers) fm.mcp_servers = a.mcp_servers;
  if (a.skills && a.skills.length) fm.skills = a.skills;
  if (a.multiagent) {
    const ma = structuredClone(a.multiagent);
    for (const list of [
      ma.subagents?.predefined_agents,
      ma.workflows?.predefined_agents,
    ]) {
      if (!list) continue;
      list.forEach((p, i) => {
        if (typeof p === "object" && p.type === "self") return; // valid API entry, passed through
        const ref = typeof p === "string" ? p : p.id;
        if (siblings.has(ref))
          list[i] = `./${ref}.md`; // path reference, resolved by ant apply
        else if (!/^agent_/.test(ref ?? ""))
          throw new Error(`${a.name}: predefined agent "${ref}" unknown`);
      });
    }
    fm.multiagent = ma;
  }
  if (a.metadata && Object.keys(a.metadata).length) fm.metadata = a.metadata;
  return `---\n# generated by scripts/agents/to-ant.mjs from ${a.name}.json – edit the JSON, not this file\n${yaml(fm)}---\n\n${a.system.trimEnd()}\n`;
}

// MODELS.md: roster table derived from the JSON (README links it instead of repeating values by hand)
function ghMode(a) {
  const mcp = (a.tools ?? []).find((t) => t.type === "mcp_toolset");
  const off = new Set(
    (mcp?.configs ?? []).filter((c) => c.enabled === false).map((c) => c.name),
  );
  if (!off.has("merge_pull_request")) return "merge";
  return off.has("create_pull_request") ? "review" : "write";
}
const webOff = (a) => {
  const ts = (a.tools ?? []).find((t) => t.type === "agent_toolset_20260401");
  return ["web_search", "web_fetch"].every((w) =>
    (ts?.configs ?? []).some((c) => c.name === w && c.enabled === false),
  );
};
let allWebOff = true;
const outputs = new Map(); // published path → content
const rows = [
  "# Models per role (generated by scripts/agents/to-ant.mjs – edit the JSON)",
  "",
  "| Agent | Model | Effort | GitHub MCP | Prompt chars |",
  "| --- | --- | --- | --- | --- |",
];
for (const f of files) {
  const a = JSON.parse(fs.readFileSync(path.join(dir, f), "utf8"));
  outputs.set(f.replace(/\.json$/, ".md"), toAnt(a));
  allWebOff = allWebOff && webOff(a);
  rows.push(
    `| ${a.name} | ${a.model.id} | ${a.model.effort?.type ?? a.model.effort ?? "default"} | ${ghMode(a)} | ${a.system.length} |`,
  );
}
rows.push(
  "",
  `"write" = PRs, comments, reviews; "review" = comments and reviews only; "merge" = may merge. Web search/fetch ${allWebOff ? "are disabled in every definition" : "are ENABLED in at least one definition"}.`,
  "",
);
outputs.set("MODELS.md", rows.join("\n"));

let stale = 0;
for (const [name, content] of outputs) {
  const out = path.join(dir, name);
  if (check) {
    const cur = fs.existsSync(out) ? fs.readFileSync(out, "utf8") : "";
    if (cur !== content) {
      stale++;
      console.log(`✗ stale: ${name}`);
    }
  } else {
    fs.writeFileSync(out, content);
    console.log(`wrote ${name} (${content.length} chars)`);
  }
}
if (check) {
  console.log(
    stale
      ? `${stale} file(s) stale – run node scripts/agents/to-ant.mjs`
      : `✓ ${outputs.size} generated files match their JSON`,
  );
  process.exit(stale ? 1 : 0);
}
